def hollow_square(n):
    for i in range(n):                          # check every row
        for j in range(n):                       # check every column in that row
            if i == 0 or i == n - 1 or j == 0 or j == n - 1:
                print("*", end="")                  # this cell is on the border
            else:
                print(" ", end="")                  # this cell is on the interior
        print()                                  # move to the next line after the row


if __name__ == "__main__":
    hollow_square(5)

