import java.util.*;

public class Main {
    void hollowSquare(int n) {
        for (int i = 0; i < n; i++) {                  // check every row
            for (int j = 0; j < n; j++) {                // check every column in that row
                if (i == 0 || i == n - 1 || j == 0 || j == n - 1) {
                    System.out.print("*");                  // this cell is on the border
                } else {
                    System.out.print(" ");                  // this cell is on the interior
                }
            }
            System.out.println();                        // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.hollowSquare(5);
    }
}

