public class Main {
    void hollowSquare(int n) {
        String border = "*".repeat(n);                 // the two border rows are identical
        String middle = "*" + " ".repeat(n - 2) + "*";  // every middle row is also identical
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(i == 0 || i == n - 1 ? border : middle);
            if (i < n - 1) {
                sb.append('\n');
            }
        }
        System.out.println(sb);                        // output the whole pattern with a single call
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.hollowSquare(5);
    }
}

